// 3. C Program to Print an Integer Entered By the User
#include <stdio.h>
int main() {
    int number;
    printf("Enter an integer: ");
    scanf("%d", &number);
    printf("You entered: %d\n", number);
    return 0;
}

// 4. C Program to Add Two Numbers
#include <stdio.h>
int main() {
    int num1, num2, sum;
    printf("Enter two numbers: ");
    scanf("%d %d", &num1, &num2);
    sum = num1 + num2;
    printf("Sum: %d\n", sum);
    return 0;
}

// 5. C Program to Check Whether a Number is Prime or Not
#include <stdio.h>
int main() {
    int num, i, isPrime = 1;
    printf("Enter a number: ");
    scanf("%d", &num);
    for(i = 2; i <= num / 2; i++) {
        if(num % i == 0) {
            isPrime = 0;
            break;
        }
    }
    if (isPrime && num > 1)
        printf("%d is a prime number.\n", num);
    else
        printf("%d is not a prime number.\n", num);
    return 0;
}

// 6. C Program to Multiply Two Floating-Point Numbers
#include <stdio.h>
int main() {
    float num1, num2, product;
    printf("Enter two numbers: ");
    scanf("%f %f", &num1, &num2);
    product = num1 * num2;
    printf("Product: %.2f\n", product);
    return 0;
}

// 7. C Program to Print the ASCII Value of a Character
#include <stdio.h>
int main() {
    char ch;
    printf("Enter a character: ");
    scanf(" %c", &ch);
    printf("ASCII value of %c: %d\n", ch, ch);
    return 0;
}

// 8. C Program to Swap Two Numbers
#include <stdio.h>
int main() {
    int a, b, temp;
    printf("Enter two numbers: ");
    scanf("%d %d", &a, &b);
    temp = a;
    a = b;
    b = temp;
    printf("After swapping: a = %d, b = %d\n", a, b);
    return 0;
}

// 9. C Program to Calculate Fahrenheit to Celsius
#include <stdio.h>
int main() {
    float fahrenheit, celsius;
    printf("Enter temperature in Fahrenheit: ");
    scanf("%f", &fahrenheit);
    celsius = (fahrenheit - 32) * 5 / 9;
    printf("Temperature in Celsius: %.2f\n", celsius);
    return 0;
}

// 10. C Program to Find the Size of int, float, double, and char
#include <stdio.h>
int main() {
    printf("Size of int: %zu bytes\n", sizeof(int));
    printf("Size of float: %zu bytes\n", sizeof(float));
    printf("Size of double: %zu bytes\n", sizeof(double));
    printf("Size of char: %zu bytes\n", sizeof(char));
    return 0;
}

// 11. C Program to Add Two Complex Numbers
#include <stdio.h>
typedef struct {
    float real;
    float imag;
} Complex;
int main() {
    Complex num1, num2, sum;
    printf("Enter real and imaginary parts of first complex number: ");
    scanf("%f %f", &num1.real, &num1.imag);
    printf("Enter real and imaginary parts of second complex number: ");
    scanf("%f %f", &num2.real, &num2.imag);
    sum.real = num1.real + num2.real;
    sum.imag = num1.imag + num2.imag;
    printf("Sum: %.2f + %.2fi\n", sum.real, sum.imag);
    return 0;
}

// 12. C Program to Print Prime Numbers From 1 to N
#include <stdio.h>
int main() {
    int n, i, j, isPrime;
    printf("Enter a number: ");
    scanf("%d", &n);
    printf("Prime numbers from 1 to %d are: ", n);
    for(i = 2; i <= n; i++) {
        isPrime = 1;
        for(j = 2; j <= i / 2; j++) {
            if(i % j == 0) {
                isPrime = 0;
                break;
            }
        }
        if (isPrime)
            printf("%d ", i);
    }
    printf("\n");
    return 0;
}

// 13. C Program to Find Simple Interest
#include <stdio.h>
int main() {
    float principal, rate, time, simpleInterest;
    printf("Enter principal amount, rate of interest and time: ");
    scanf("%f %f %f", &principal, &rate, &time);
    simpleInterest = (principal * rate * time) / 100;
    printf("Simple Interest: %.2f\n", simpleInterest);
    return 0;
}

// 14. C Program to Find Compound Interest
#include <stdio.h>
#include <math.h>
int main() {
    float principal, rate, time, compoundInterest;
    printf("Enter principal amount, rate of interest and time: ");
    scanf("%f %f %f", &principal, &rate, &time);
    compoundInterest = principal * pow((1 + rate / 100), time) - principal;
    printf("Compound Interest: %.2f\n", compoundInterest);
    return 0;
}

// 15. C Program for Area and Perimeter of Rectangle
#include <stdio.h>
int main() {
    float length, width, area, perimeter;
    printf("Enter length and width of the rectangle: ");
    scanf("%f %f", &length, &width);
    area = length * width;
    perimeter = 2 * (length + width);
    printf("Area: %.2f\n", area);
    printf("Perimeter: %.2f\n", perimeter);
    return 0;
}"}

